import * as G from './b26-geometry.js';
import {sides,roleCorrect,inspect} from './b26-model.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(name,label,attr='')=>`<button type="button" data-x="g26-${name}" ${attr}>${esc(label)}</button>`;
const f=(name,label,value,extra='')=>`<label class="g26-field"><span>${esc(label)}</span><input data-xfield="${name}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,value,options)=>`<label class="g26-field"><span>${esc(label)}</span><select data-xfield="${name}"><option value="">选择</option>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const qs=(t,m)=>(t.questions||[]).map((q,i)=>q.options?select('answers.'+i,q.label,m.answers[i],q.options):f('answers.'+i,q.label,m.answers[i],'inputmode="decimal"')).join('');
const line=(a,b,attrs='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" ${attrs}/>`;
const svg=(body,label,box='0 0 760 430')=>`<svg class="g26-svg" viewBox="${box}" role="img" aria-label="${esc(label)}">${body}</svg>`;
const fmt=x=>String(Number(x.toFixed(3)));
const fit=(points,box={x:50,y:25,w:660,h:340})=>{const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),k=Math.min(box.w/Math.max(1,xmax-xmin),box.h/Math.max(1,ymax-ymin)),cx=(xmin+xmax)/2,cy=(ymin+ymax)/2;return p=>[box.x+box.w/2+(p[0]-cx)*k,box.y+box.h/2-(p[1]-cy)*k];};
const mid=(a,b)=>[(a[0]+b[0])/2,(a[1]+b[1])/2];
function marker(p){const v=p[0],u=[p[1][0]-v[0],p[1][1]-v[1]],w=[p[2][0]-v[0],p[2][1]-v[1]],a=Math.hypot(...u),b=Math.hypot(...w),q=[v[0]+u[0]*15/a,v[1]+u[1]*15/a],r=[v[0]+w[0]*15/b,v[1]+w[1]*15/b],z=[q[0]+w[0]*15/b,q[1]+w[1]*15/b];return`<path d="M ${q} L ${z} L ${r}" fill="none" stroke="#496f5c" stroke-width="2.5"/>`;}
function edges(ps,selected,labels={},roleLabels={},showNames=true){let s='';for(let i=0;i<3;i++){const a=ps[i],b=ps[(i+1)%3],m=mid(a,b),center=ps.reduce((z,p)=>[z[0]+p[0]/3,z[1]+p[1]/3],[0,0]),dx=m[0]-center[0],dy=m[1]-center[1],d=Math.hypot(dx,dy)||1,lx=m[0]+dx/d*22,ly=m[1]+dy/d*22,anchor=dx/d<-.35?'end':dx/d>.35?'start':'middle',active=selected===i;s+=line(a,b,`stroke="${active?'#bc7641':'#4e7762'}" stroke-width="${active?7:5}" stroke-linecap="round"`)+line(a,b,`stroke="transparent" stroke-width="25" role="button" tabindex="0" aria-label="选择边${i+1}" data-x="g26-edge" data-index="${i}"`);let text='边'+(i+1)+(labels[i]!==undefined?' · '+labels[i]:'')+(roleLabels[i]?' · '+roleLabels[i]:'');if(showNames)s+=`<text x="${lx}" y="${ly}" text-anchor="${anchor}" class="g26-edge-label">${esc(text)}</text>`;}return s;}
function hypEdges(ps,selected,showNames=true){return edges(ps,selected,{}, {},showNames).replaceAll('data-x="g26-edge"','data-x="g26-hyp"');}
function areaVisual(t,b){const p=G.rotateAll(G.triangle(t.a*b.scale,t.b*b.scale),t.rotation||0),squares=[0,1,2].map(i=>G.squareOnEdge(p,i)),reference=G.rotateAll(G.triangle(t.a*2,t.b*2),t.rotation||0),referenceSquares=[0,1,2].map(i=>G.squareOnEdge(reference,i)),to=fit(referenceSquares.flat()),poly=ps=>ps.map(to).map(q=>q.join(',')).join(' '),colors=['#b9d7c7','#e6c28d','#adc8df'];let s='';squares.forEach((sq,i)=>{s+=`<polygon points="${poly(sq)}" fill="${colors[i]}" fill-opacity=".7" stroke="#729283" stroke-width="2"/>`;if(b.seen.includes(b.scale)){const center=sq.reduce((z,p)=>[z[0]+p[0]/4,z[1]+p[1]/4],[0,0]),q=to(center);s+=`<text x="${q[0]}" y="${q[1]}" text-anchor="middle" class="g26-area-number">${fmt(G.area(sq))}</text>`;}});const ps=p.map(to);s+=`<polygon points="${poly(p)}" fill="#f9fbf4" stroke="#4e7762" stroke-width="3"/>`+marker(ps)+hypEdges(ps,b.hyp,!b.seen.includes(b.scale));let result=svg(s,'直角三角形三条边上各画出的正方形');if(b.seen.includes(b.scale)){const a=(t.a*b.scale)**2,c=(t.b*b.scale)**2,total=a+c,k=490/(4*(t.a*t.a+t.b*t.b));result+=svg(`<text x="20" y="26">两个小正方形的面积</text><rect x="230" y="5" width="${a*k}" height="25" fill="#b9d7c7"/><rect x="${230+a*k}" y="5" width="${c*k}" height="25" fill="#adc8df"/><text x="20" y="72">斜边上正方形的面积</text><rect x="230" y="51" width="${total*k}" height="25" fill="#e6c28d"/><text x="230" y="96">${fmt(a)} + ${fmt(c)} = ${fmt(total)}</text>`,'相同单位的面积条对齐比较，放大前后使用同一尺度','0 0 760 105');}return result+`<p class="g26-caption">${b.seen.length?'已比较：'+b.seen.map(n=>n===1?'原大小':'两倍').join('、'):'先选直角对面的边，再比较三个正方形。'}</p>`;}
function checkVisual(t,b){let s='';t.shapes.forEach((shape,i)=>{const p=G.rotateAll(shape,i?30:0),to=fit(p,{x:30+i*360,y:55,w:290,h:230}),ps=p.map(to);s+=`<polygon points="${ps.map(q=>q.join(',')).join(' ')}" fill="#d9e9dc" stroke="#5c806c" stroke-width="4"/>`;const v=G.rightVertex(p);if(b.tested.includes(i)){if(v>=0){const reordered=[ps[v],ps[(v+1)%3],ps[(v+2)%3]];s+=marker(reordered);}s+=`<text x="${175+i*360}" y="330" text-anchor="middle">${v>=0?'检查到直角':'没有直角'}</text>`;}s+=`<text x="${175+i*360}" y="380" text-anchor="middle">图${i+1}${b.choice===i?' · 已选':''}</text>`;});return svg(s,'比较两个三角形，检查是否存在直角');}
function coordPoints(t,b){const [p,q]=t.points;if(!b.corner)return null;const r=b.corner==='hfirst'?[q[0],p[1]]:[p[0],q[1]];return[r,b.corner==='hfirst'?p:q,b.corner==='hfirst'?q:p];}
function coordinateVisual(t,b){const [x0,x1,y0,y1]=t.domain||[0,6,0,6],origin=[210,375],step=48,to=p=>[origin[0]+p[0]*step,origin[1]-p[1]*step];let s='';for(let x=x0;x<=x1;x++){s+=line(to([x,y0]),to([x,y1]),`stroke="${x===0?'#6d947a':'#d4dfd0'}" stroke-width="${x===0?2:1}"`)+`<text x="${to([x,0])[0]}" y="${origin[1]+23}" text-anchor="middle">${x}</text>`;}for(let y=y0;y<=y1;y++){s+=line(to([x0,y]),to([x1,y]),`stroke="${y===0?'#6d947a':'#d4dfd0'}" stroke-width="${y===0?2:1}"`)+`<text x="${origin[0]-15}" y="${to([0,y])[1]+5}" text-anchor="end">${y}</text>`;}const p=coordPoints(t,b);if(p){const ps=p.map(to);s+=`<polygon points="${ps.map(q=>q.join(',')).join(' ')}" fill="#e1eee1" fill-opacity=".6" stroke="#648b72" stroke-width="3"/>`+marker(ps)+hypEdges(ps,b.hyp);const ls=G.edgeLengths(p),labels=[fmt(ls[0]),'?',fmt(ls[2])];for(let i=0;i<3;i++){const q=mid(ps[i],ps[(i+1)%3]);s+=`<text x="${q[0]-8}" y="${q[1]+21}" text-anchor="middle" class="g26-length">${labels[i]}</text>`;}}else s+=line(to(t.points[0]),to(t.points[1]),'stroke="#ad815b" stroke-width="4" stroke-dasharray="6 5"');for(const pt of t.points){const z=to(pt);s+=`<circle cx="${z[0]}" cy="${z[1]}" r="6" fill="#3f6c53"/><text x="${z[0]+10}" y="${z[1]-10}">(${pt})</text>`;}return svg(s,'坐标网格里的两点，连接水平和竖直边得到直角三角形');}
function lengthVisual(t,b){if(t.coord)return coordinateVisual(t,b);const p=G.rotateAll(G.triangle(t.a,t.b),t.rotation||0),to=fit(p,{x:125,y:45,w:510,h:290}),ps=p.map(to),ls=G.edgeLengths(p),labels=t.unknown==='leg'?{0:fmt(ls[0]),1:fmt(ls[1]),2:'?'}:{0:fmt(ls[0]),1:'?',2:fmt(ls[2])};let s=`<polygon points="${ps.map(q=>q.join(',')).join(' ')}" fill="#e1eee1" stroke="#648b72" stroke-width="3"/>`+marker(ps)+hypEdges(ps,b.hyp);for(let i=0;i<3;i++){const q=mid(ps[i],ps[(i+1)%3]);s+=`<text x="${q[0]-8}" y="${q[1]+22}" text-anchor="middle" class="g26-length">${esc(labels[i])}</text>`;}return svg(s,'直角三角形的三条边和待求长度');}
function trigVisual(t,b){const[a0,b0,h0]=sides(t),p=G.rotateAll(G.triangle(a0*b.scale,b0*b.scale),t.rotation||0),maxScale=t.mode==='compare'?2:1,reference=G.rotateAll(G.triangle(a0*maxScale,b0*maxScale),t.rotation||0),to=fit(reference,{x:130,y:45,w:500,h:285}),ps=p.map(to),labels={};if(['roles','compare'].includes(t.mode)){labels[0]=fmt(a0*b.scale);labels[1]=fmt(h0*b.scale);labels[2]=fmt(b0*b.scale);}else if(t.mode==='solve'){labels[1]=fmt(h0);labels[t.unknown==='opp'?2:0]='?';}else{labels[0]=fmt(a0);labels[2]=fmt(b0);}
 let roleLabels={};if(b.ref){const names={hyp:'斜边',opp:'对边',adj:'邻边'};for(const[k,i]of Object.entries(b.roles[String(b.ref)]))if(i!==null)roleLabels[i]=names[k];}
 let s=`<polygon points="${ps.map(q=>q.join(',')).join(' ')}" fill="#e1eee1" stroke="#648b72" stroke-width="3"/>`+marker(ps)+edges(ps,b.selected,labels,roleLabels);
 ps.forEach((p,i)=>{const c=ps.reduce((z,q)=>[z[0]+q[0]/3,z[1]+q[1]/3],[0,0]),dx=p[0]-c[0],dy=p[1]-c[1],d=Math.hypot(dx,dy)||1,x=p[0]+dx/d*20,y=p[1]+dy/d*20,anchor=dx/d<-.3?'end':dx/d>.3?'start':'middle';s+=`<circle cx="${p[0]}" cy="${p[1]}" r="${b.ref===i?11:5}" fill="${b.ref===i?'#b87340':'#496f5c'}"/>`+`<text x="${x}" y="${y}" text-anchor="${anchor}">${['直角','B角','C角'][i]}</text>`;});
 if(b.ref===1&&t.mode==='solve')s+=`<text x="${ps[1][0]-48}" y="${ps[1][1]-12}">${t.angle}°</text>`;if(b.ref===1&&t.mode==='inverse')s+=`<text x="${ps[1][0]-36}" y="${ps[1][1]-12}">?°</text>`;
 let v=svg(s,'直角三角形，选择观察角后给三条边标记');if(b.observations.length)v+=`<div class="g26-records">${b.observations.map(o=>`<p>${o.scale===1?'原大小':'两倍'}：对边 ${fmt(o.opposite)} ÷ 斜边 ${fmt(o.hypotenuse)} = ${fmt(o.ratio)}</p>`).join('')}</div>`;return v;}
export function visual(t,m){let v='';if(t.type==='x-g26-area')v=areaVisual(t,m.board);if(t.type==='x-g26-check')v=checkVisual(t,m.board);if(t.type==='x-g26-length')v=lengthVisual(t,m.board);if(t.type==='x-g26-trig')v=trigVisual(t,m.board);return`<div class="g26-world">${v}</div>`;}
const edgeButtons=action=>`<div class="g26-buttons">${[0,1,2].map(i=>btn(action,'选边'+(i+1),`data-index="${i}"`)).join('')}</div>`;
export function controls(t,m){const b=m.board;let v='',ready=false;
 if(t.type==='x-g26-area'){v=edgeButtons('hyp')+select('scale','正方形与三角形一起变大',m.scale,[['1','原大小'],['2','两倍']])+btn('scale','改变大小')+btn('look','比较面积');ready=b.seen.includes(1)&&b.seen.includes(2);}
 if(t.type==='x-g26-check'){v=`<div class="g26-buttons">${t.shapes.map((_,i)=>btn('probe','检查图'+(i+1)+(b.tested.includes(i)?' ✓':''),`data-index="${i}"`)).join('')}</div><div class="g26-buttons">${t.shapes.map((_,i)=>btn('choose',(b.choice===i?'✓ ':'')+'选图'+(i+1),`data-index="${i}"`)).join('')}</div>`;ready=b.choice!==null&&b.tested.length===t.shapes.length;}
 if(t.type==='x-g26-length'){if(t.coord)v=`<div class="g26-buttons">${btn('corner','先横后竖',`data-index="hfirst"`)}${btn('corner','先竖后横',`data-index="vfirst"`)}</div>`;if(!t.coord||b.corner)v+=edgeButtons('hyp');if(b.hyp===1)v+=`<p class="g26-caption">要找的那条边对应的正方形，是把已知面积合起来，还是从总面积中去掉一部分？</p><div class="g26-buttons">${btn('op','相加',`data-index="add"`)}${btn('op','相减',`data-index="subtract"`)}</div>`;if(b.op)v+=btn('help','帮我理解面积和边长')+(b.help?'<p class="g26-caption">一条边乘自己，是它所作正方形的面积。例如 5 × 5 = 25；反过来找哪个数乘自己得到25，就是从面积25找边长5。</p>':'')+f('square','未知边对应的面积',m.square,'inputmode="decimal"')+f('result','未知边的长度',m.result,'inputmode="decimal"')+btn('save','记下结果');ready=!!b.saved;}
 if(t.type==='x-g26-trig'){
  v=`<div class="g26-buttons">${btn('ref',(b.ref===1?'✓ ':'')+'从B角看',`data-index="1"`)}${btn('ref',(b.ref===2?'✓ ':'')+'从C角看',`data-index="2"`)}</div>`;
  if(b.ref){if(b.confirmed.includes(b.ref)&&!b.editing)v+=btn('edit','调整边的名字');else{v+='<p class="g26-caption">先找直角对面的斜边；从所选角看，隔着的是对边，挨着且不是斜边的是邻边。</p>';v+=edgeButtons('edge');if(b.selected!==null)v+=`<div class="g26-buttons">${btn('assign','标作斜边',`data-index="hyp"`)}${btn('assign','标作对边',`data-index="opp"`)}${btn('assign','标作邻边',`data-index="adj"`)}</div>`;v+=btn('confirm','检查这三条边');}}
  if(t.mode==='roles')ready=b.confirmed.includes(1)&&b.confirmed.includes(2)&&roleCorrect(b,1)&&roleCorrect(b,2);
  if(t.mode==='compare'&&b.ref===1&&b.confirmed.includes(1)){v+=select('scale','让三角形一起变大',m.scale,[['1','原大小'],['2','两倍']])+btn('scale','改变大小')+btn('observe','记下边长和比例');ready=[1,2].every(x=>b.observations.some(o=>o.scale===x));}
  if(['solve','inverse'].includes(t.mode)&&b.ref===1&&b.confirmed.includes(1)){v+=`<p class="g26-caption">选用包含已知边和要找的边的关系：</p><div class="g26-buttons">${btn('ratio','sin：对边 ÷ 斜边',`data-index="sin"`)}${btn('ratio','cos：邻边 ÷ 斜边',`data-index="cos"`)}${btn('ratio','tan：对边 ÷ 邻边',`data-index="tan"`)}</div>`;if(b.ratio){v+=btn('help','帮我理解比例')+(b.help?'<p class="g26-caption">比例是上面的边除以下面的边；知道比例和下面的边，可以相乘找上面的边。要找角度，可以把比例交给对应的反算功能。</p>':'')+`<p class="g26-caption">当前选择：${esc(b.ratio)}</p><details class="g26-fold" ${b.calculator?'open':''}><summary>用计算器算比例或角度（可选）</summary>${select('calcKind','选择计算',m.calcKind,[['sin','sin（输入角度）'],['cos','cos（输入角度）'],['tan','tan（输入角度）'],['asin','反算角 asin'],['acos','反算角 acos'],['atan','反算角 atan'],['sqrt','平方根']])}${f('calcInput','输入数值',m.calcInput,'inputmode="decimal"')}${btn('calc','算一算')}${b.calculator?`<p class="g26-caption">计算器：${esc(b.calculator.kind)}(${esc(b.calculator.input)}) ≈ ${fmt(b.calculator.result)}${b.calculator.kind.startsWith('a')?'°':''}</p>`:''}</details>${f('result',t.mode==='inverse'?'求出的角度（度）':'求出的边长',m.result,'inputmode="decimal"')}${btn('answer','记下结果')}`;}ready=!!b.saved;}
 }
 if(ready)v+=qs(t,m);if(m.issue)v+=`<p class="g26-issue" role="status">${esc(m.issue)}</p>`;if(inspect(t,m).correct)v=`<details class="g26-fold"><summary>查看或修改刚才的操作</summary>${v}</details>`;v+=`<details class="g26-fold"><summary>用自己的话留下发现（可选）</summary>${f('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断这段解释。</small></details>`;return`<div class="g26-controls">${v}</div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
